package com.hbm.machine.excavator;
import java.util.List;import com.hbm.conveyor.ConveyorObjects;import net.minecraft.core.registries.Registries;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.flag.FeatureFlags;import net.minecraft.world.inventory.MenuType;import net.minecraft.world.item.*;import net.minecraft.world.level.block.entity.BlockEntityType;import net.neoforged.bus.api.IEventBus;import net.neoforged.fml.ModContainer;import net.neoforged.neoforge.capabilities.*;import net.neoforged.neoforge.items.wrapper.*;import net.neoforged.neoforge.network.IContainerFactory;import net.neoforged.neoforge.registries.*;
public final class ExcavatorContent {
 private static final DeferredRegister.Blocks BLOCKS=DeferredRegister.createBlocks("hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");private static final DeferredRegister<BlockEntityType<?>> ENTITIES=DeferredRegister.create(Registries.BLOCK_ENTITY_TYPE,"hbm");private static final DeferredRegister<MenuType<?>> MENUS=DeferredRegister.create(Registries.MENU,"hbm");
 public static final DeferredBlock<ExcavatorBlock> BLOCK=BLOCKS.register("machine_excavator",ExcavatorBlock::new);public static final DeferredItem<BlockItem> ITEM=ITEMS.registerSimpleBlockItem(BLOCK);public static final DeferredBlock<BarricadeBlock> BARRICADE=BLOCKS.register("barricade",BarricadeBlock::new);public static final DeferredItem<BlockItem> BARRICADE_ITEM=ITEMS.registerSimpleBlockItem(BARRICADE);
 public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<ExcavatorBlockEntity>> ENTITY=ENTITIES.register("excavator",()->BlockEntityType.Builder.of(ExcavatorBlockEntity::new,BLOCK.get()).build(null));public static final DeferredHolder<BlockEntityType<?>,BlockEntityType<ExcavatorPort>> PORT=ENTITIES.register("excavator_port",()->BlockEntityType.Builder.of(ExcavatorPort::new,BLOCK.get()).build(null));public static final DeferredHolder<MenuType<?>,MenuType<ExcavatorMenu>> MENU=MENUS.register("excavator",()->new MenuType<>((IContainerFactory<ExcavatorMenu>)ExcavatorMenu::new,FeatureFlags.DEFAULT_FLAGS));
 public static ResourceLocation id(String name){return ResourceLocation.fromNamespaceAndPath("hbm",name);}public static void register(IEventBus bus,ModContainer container){BLOCKS.register(bus);ITEMS.register(bus);ENTITIES.register(bus);MENUS.register(bus);bus.addListener(ExcavatorContent::capabilities);bus.addListener(ExcavatorControl::register);ConveyorObjects.register(bus,container);}private static void capabilities(RegisterCapabilitiesEvent event){event.registerBlockEntity(Capabilities.ItemHandler.BLOCK,ENTITY.get(),(machine,side)->side==null?new InvWrapper(machine):new SidedInvWrapper(machine,side));}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("machine")?List.of(new ItemStack(ITEM.get())):List.of();}private ExcavatorContent(){}
}
